function node(tag, className, text){ const n=document.createElement(tag); if(className)n.className=className; if(text!==undefined)n.textContent=text; return n; }
function money(value){ if(value===null||value===undefined)return '—'; const [whole,decimal]=String(value).split('.'); return whole.replace(/\B(?=(\d{3})+(?!\d))/g,',')+(decimal!==undefined?'.'+decimal:''); }
function sourceTime(value){ if(!value)return 'Unavailable'; return value.replace('T',' ').slice(0,19); }
function badge(record){ const b=node('span','badge'+(!record.needs_review?' good':'')); b.append(node('span','badge-dot'),node('span','',record.reconciliation_status==='matched'&&record.needs_review?'Matched · review':labels[record.reconciliation_status]||record.reconciliation_status)); return b; }
function params(includePage=false){ const q=new URLSearchParams(state.filters); if(includePage){q.set('review_only',String(state.reviewOnly));q.set('limit','50');if(state.cursors[state.index])q.set('cursor',state.cursors[state.index]);} return q; }
async function api(path){ const response=await fetch(path,{cache:'no-store'}); const data=await response.json(); if(!response.ok)throw new Error(data.error||'The request could not be completed.'); return data; }
function syncControls(){const value=state.busy||tracking.busy||due.busy||offers.busy;document.body.classList.toggle('loading',value);for(const id of ['apply','reset','review-only','country','start','end','status','view-home','view-overview','view-counterparts','view-due','view-offer','refresh-results','overview-open-swaps','overview-paid-dues','overview-offers','gap-group','due-group','offer-group',...Object.keys(groupInfo).map(group=>'group-'+group)])el(id).disabled=value;el('export').disabled=value||state.failed;el('previous').disabled=value||state.failed||state.index===0;el('next').disabled=value||state.failed||!state.page?.has_more;el('gap-export').disabled=value||tracking.failed||!tracking.page;el('gap-previous').disabled=value||tracking.failed||tracking.index===0;el('gap-next').disabled=value||tracking.failed||!tracking.page?.has_more;el('due-export').disabled=value||due.failed||!due.page;el('due-previous').disabled=value||due.failed||due.index===0;el('due-next').disabled=value||due.failed||!due.page?.has_more;el('offer-export').disabled=value||offers.failed||!offers.page;el('offer-previous').disabled=value||offers.failed||offers.index===0;el('offer-next').disabled=value||offers.failed||!offers.page?.has_more;el('offer-rows').setAttribute('aria-busy',String(offers.busy));el('rows').setAttribute('aria-busy',String(state.busy));el('gap-rows').setAttribute('aria-busy',String(tracking.busy));el('due-rows').setAttribute('aria-busy',String(due.busy));}
function busy(value){state.busy=value;syncControls();}
function error(message){el('error').hidden=!message;el('error').textContent=message||'';}
function renderSummary(){
  const s=state.summary; el('total').textContent=number(s.deduction_count);el('matched').textContent=number(s.groups.filter(g=>g.status==='matched').reduce((sum,g)=>sum+g.deduction_count,0));el('review').textContent=number(s.needs_review_count);el('unmatched').textContent=number(s.groups.filter(g=>g.status==='no_swap_in_loaded_data').reduce((sum,g)=>sum+g.deduction_count,0));
  const countries=new Map(); for(const g of s.groups){if(!countries.has(g.country))countries.set(g.country,{total:0,matched:0,review:0,currencies:new Set()});const c=countries.get(g.country);c.total+=g.deduction_count;c.review+=g.needs_review_count;if(g.status==='matched')c.matched+=g.deduction_count;c.currencies.add(g.currency||'Unknown currency');}
  el('countries').replaceChildren(); if(!countries.size){el('countries').append(node('div','country-placeholder','No deductions match the selected filters.'));return;}
  for(const [name,c] of countries){const card=node('article','country-card');const top=node('div','country-top');top.append(node('span','country-icon',name==='Kenya'?'KE':'RW'));const title=node('div');title.append(node('h3','',name),node('div','currency-label',Array.from(c.currencies).join(' · ')));top.append(title);const rate=node('div','rate',(100*c.matched/c.total).toFixed(2)+'%');rate.append(node('span','','matched'));top.append(rate);const track=node('div','progress-track');const fill=node('div','progress-good');fill.style.width=(100*c.matched/c.total)+'%';track.append(fill);const stats=node('div','country-stats');for(const [label,count]of [['Deductions',c.total],['Matched',c.matched],['Review',c.review]]){const text=node('span','',label+' ');text.append(node('b','',number(count)));stats.append(text);}card.append(top,track,stats);el('countries').append(card);}
}
function renderSwapReview(s){if(s&&s.resolved_offer_count===undefined)throw new Error('Stop the current PyCharm run and run main.py again to activate offer resolutions.');el('swap-review-open').textContent=s?number(s.open_count):'—';el('swap-review-resolved').textContent=s?number(s.resolved_paid_due_count):'—';el('swap-review-offers').textContent=s?number(s.resolved_offer_count):'—';el('swap-review-countries').textContent=s?s.by_country.map(g=>g.country+': '+number(g.open_count)+' open · '+number(g.resolved_paid_due_count)+' Paid Dues · '+number(g.resolved_offer_count)+' offers cleared').join(' | ')||'No swaps without wallet deductions match these filters.':'Restart main.py to load offer resolutions.';}

function renderRows(){
  const records=state.page.records;el('rows').replaceChildren(); const total=state.reviewOnly?state.summary.needs_review_count:state.summary.deduction_count;el('case-count').textContent=number(total);el('table-caption').textContent=state.reviewOnly?'Unmatched deductions and matched records with additional review flags.':'All deductions matching your country, date and result filters.';
  if(!records.length){const tr=node('tr');const td=node('td','empty-state','No transactions match these filters. Try a different country or date range.');td.colSpan=7;tr.append(td);el('rows').append(tr);}
  for(const r of records){const tr=node('tr');const customer=node('td');customer.append(node('div','customer-name',r.wallet_customer_name||'Customer unavailable'),node('div','cell-sub',r.wallet_customer_reference||r.wallet_code||'No customer reference'));const country=node('td');country.append(node('span','country-chip',r.country||'Unknown'));const ref=node('td');const primary=node('div','reference',r.wallet_reference||r.transaction_id||'Missing reference');primary.title=r.wallet_reference||r.transaction_id||'';ref.append(primary,node('div','cell-sub',r.transaction_id||'No Transaction ID'));const amount=node('td','amount-column');amount.append(node('span','amount',money(r.wallet_amount)),node('span','amount-currency',r.wallet_currency||'?'));const result=node('td');result.append(badge(r));const extraReasons=r.review_reasons.filter(value=>value!==r.reconciliation_status);if(extraReasons.length){const reason=node('div','reason-sub',extraReasons.map(v=>labels[v]||v.replaceAll('_',' ')).join(' · '));reason.title=reason.textContent;result.append(reason);}const date=node('td','',sourceTime(r.wallet_created_on));const action=node('td');const open=node('button','open-button','View ↗');open.setAttribute('aria-label','View transaction '+(r.wallet_reference||r.wallet_record_id));open.addEventListener('click',()=>openDetail(r));action.append(open);tr.append(customer,country,ref,amount,result,date,action);el('rows').append(tr);}
  const from=records.length?state.index*50+1:0;const to=records.length?state.index*50+records.length:0;el('page-info').textContent=`Showing ${number(from)}–${number(to)} of ${number(total)}`;el('previous').disabled=state.index===0;el('next').disabled=!state.page.has_more;
}
async function load(all=true){if(state.busy){state.refreshPending=true;return;}busy(true);error();try{const data=await api((all?'/api/dashboard?':'/api/records?')+params(true));if(all){state.summary=data.summary;renderSummary();renderSwapReview(data.swap_review);}state.failed=false;state.page=data.page;renderRows();el('updated').textContent='Refreshed '+new Date(data.generated_at_utc).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}catch(e){state.failed=true;state.page=null;renderSwapReview();error(e.message);el('updated').textContent='Refresh failed';for(const id of ['total','matched','review','unmatched','case-count'])el(id).textContent='—';el('countries').replaceChildren(node('div','country-placeholder','Results are unavailable. Apply filters again to retry.'));const tr=node('tr');const td=node('td','empty-state','The results could not be loaded. Please retry.');td.colSpan=7;tr.append(td);el('rows').replaceChildren(tr);el('page-info').textContent='Results unavailable';}finally{busy(false);if(state.refreshPending){state.refreshPending=false;load();}}}
function readFilters(){const filters={};for(const id of ['country','start','end','status'])if(el(id).value)filters[id]=el(id).value;return filters;}
function resetPages(){state.cursors=[null];state.index=0;tracking.cursors=[null];tracking.index=0;due.cursors=[null];due.index=0;offers.cursors=[null];offers.index=0;}
function loadActive(){if(currentView==='home')return;if(currentView==='counterparts')return loadTracking();if(currentView==='due')return loadDue();if(currentView==='offer')return loadOffers();return load();}
el('filters').addEventListener('submit',event=>{event.preventDefault();const filters=readFilters();if(currentView!=='overview')delete filters.status;if(filters.start&&filters.end&&filters.start>filters.end){error('The from date must not be after the through date.');return;}state.filters=filters;resetPages();loadActive();});
el('reset').addEventListener('click',()=>{HTMLFormElement.prototype.reset.call(el('filters'));el('review-only').checked=true;state.reviewOnly=true;state.filters={};resetPages();loadActive();});
el('review-only').addEventListener('change',()=>{state.reviewOnly=el('review-only').checked;state.cursors=[null];state.index=0;load();});
el('next').addEventListener('click',()=>{if(state.busy||!state.page?.has_more)return;state.cursors[state.index+1]=state.page.next_cursor;state.index++;load(false);});
el('previous').addEventListener('click',()=>{if(state.busy||!state.index)return;state.index--;load(false);});
function field(grid,label,value){grid.append(node('dt','',label),node('dd','',Array.isArray(value)?value.join(', '):(value??'Unavailable')));}
async function openDetail(record){
  state.returnFocus=document.activeElement;state.selected=record;el('drawer').hidden=false;el('drawer-overlay').hidden=false;el('drawer-content').replaceChildren(node('p','','Loading transaction details…'));el('close-drawer').focus();
  try{const data=await api('/api/detail?'+new URLSearchParams({record_id:record.wallet_record_id,country:record.country}));if(state.selected!==record)return;const r=data.record;const body=el('drawer-content');body.replaceChildren(node('h2','',r.wallet_customer_name||'Transaction details'),badge(r));const reasons=node('div','reason-list');for(const reason of r.review_reasons.filter(value=>value!==r.reconciliation_status))reasons.append(node('span','badge',labels[reason]||reason.replaceAll('_',' ')));body.append(reasons);
    let grid=node('dl','detail-grid');field(grid,'Country',r.country);field(grid,'Customer reference',r.wallet_customer_reference);field(grid,'Customer lookup',r.wallet_customer_id);field(grid,'Wallet',r.wallet_code||r.wallet_id);body.append(node('h3','','Customer & wallet'),grid);
    grid=node('dl','detail-grid');field(grid,'Reference',r.wallet_reference);field(grid,'Transaction ID',r.transaction_id);field(grid,'Record ID',r.wallet_record_id);field(grid,'Amount',money(r.wallet_amount)+' '+(r.wallet_currency||''));field(grid,'Created on',sourceTime(r.wallet_created_on));field(grid,'Deductions sharing reference',r.wallet_count);body.append(node('h3','','Wallet deduction'),grid);
    grid=node('dl','detail-grid');field(grid,'Loaded swaps',r.swap_count);field(grid,'Successful swaps',r.successful_swap_count);field(grid,'Successful swap amount',money(r.successful_swap_amount));field(grid,'Successful swap created',sourceTime(r.successful_swap_created_on));field(grid,'Swap references',r.swap_references?.length?r.swap_references:null);field(grid,'Payment methods',r.successful_payment_methods?.length?r.successful_payment_methods:null);field(grid,'Customer comparison',r.swap_customer_lookup_check.replaceAll('_',' '));body.append(node('h3','','Swap comparison'),grid);
    grid=node('dl','detail-grid');field(grid,'Date context',labels[r.coverage_assessment]||r.coverage_assessment);field(grid,'Observed swap start',sourceTime(r.observed_first_swap));field(grid,'Observed swap end',sourceTime(r.observed_last_swap));body.append(node('h3','','Source coverage'),grid,node('p','detail-note','Review flags indicate records to investigate. Export coverage and refund eligibility have not been verified. Customer details and currency reflect the current wallet snapshot.'));
  }catch(e){if(state.selected===record)el('drawer-content').replaceChildren(node('p','error-banner',e.message));}
}
function closeDetail(){state.selected=null;el('drawer').hidden=true;el('drawer-overlay').hidden=true;state.returnFocus?.focus({preventScroll:true});}
el('close-drawer').addEventListener('click',closeDetail);el('drawer-overlay').addEventListener('click',closeDetail);document.addEventListener('keydown',event=>{if(event.key==='Escape')closeDetail();if(event.key==='Tab'&&!el('drawer').hidden){event.preventDefault();el('close-drawer').focus();}});
el('export').addEventListener('click',async()=>{if(state.busy)return;busy(true);error();el('export').textContent='Exporting…';try{const response=await fetch('/api/export?'+params());if(!response.ok){const data=await response.json();throw new Error(data.error||'Export failed.');}const url=URL.createObjectURL(await response.blob());const link=node('a');link.href=url;link.download='spiro_review_candidates.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error(e.message);}finally{el('export').textContent='↓ Export candidates';busy(false);if(state.refreshPending){state.refreshPending=false;loadActive();}}});
function trackingParams(includePage=false){const q=new URLSearchParams();for(const key of ['country','start','end'])if(state.filters[key])q.set(key,state.filters[key]);q.set('group',tracking.group);if(includePage){q.set('limit','50');if(tracking.cursors[tracking.index])q.set('cursor',tracking.cursors[tracking.index]);}return q;}
function trackingEmpty(message){const tr=node('tr');const td=node('td','empty-state',message);td.colSpan=8;tr.append(td);el('gap-rows').replaceChildren(tr);}
function renderTracking(){
  const groups=tracking.summary.groups;for(const key of Object.keys(groupInfo)){el('count-'+key).textContent=number(groups[key].count);el('group-'+key).setAttribute('aria-pressed',String(key===tracking.group));el('group-'+key).classList.toggle('selected',key===tracking.group);const countries=el('countries-'+key);if(countries)countries.textContent=Object.entries(groups[key].by_country).map(([name,count])=>name+' '+number(count)).join(' · ')||'No records in this selection';}
  const info=groupInfo[tracking.group];el('gap-table-title').textContent=info.title;el('gap-caption').textContent=info.caption;el('gap-group').value=tracking.group;
  const records=tracking.page.records;el('gap-rows').replaceChildren();if(!records.length)trackingEmpty('No records in this group match the selected country and dates.');
  for(const r of records){const wallet=r.record_type==='Wallet deduction';const tr=node('tr');const customer=node('td');customer.append(node('div','customer-name',r.customer_name||'Customer unavailable'),node('div','cell-sub',r.customer_reference||r.mapped_customer_references?.join(', ')||r.customer_id||'No customer reference'));const country=node('td');country.append(node('span','country-chip',r.country||'Unknown'));const ref=node('td');const reference=r.wallet_reference||r.swap_reference||r.record_id;const primary=node('div','reference',reference);primary.title=reference;ref.append(primary,node('div','cell-sub',r.transaction_id?.trim()?r.transaction_id:'No Transaction ID'));const amount=node('td','amount-column');amount.append(node('span','amount',money(wallet?r.wallet_amount:r.swap_amount)),node('span','amount-currency',r.currency||'?'));const reason=node('td');reason.append(node('span','badge',gapReasons[r.missing_counterpart_reason]||r.missing_counterpart_reason));const method=node('td');method.append(node('div','',wallet?'Wallet debit':r.payment_method||'Payment method unavailable'),node('div','cell-sub',wallet?r.wallet_status:r.swap_status));const date=node('td','',sourceTime(r.created_on));const action=node('td');const open=node('button','open-button','View ↗');open.setAttribute('aria-label','View '+r.record_type.toLowerCase()+' '+reference);open.addEventListener('click',()=>openTrackingDetail(r));action.append(open);tr.append(customer,country,ref,amount,reason,method,date,action);el('gap-rows').append(tr);}
  const from=records.length?tracking.index*50+1:0;const to=records.length?tracking.index*50+records.length:0;el('gap-page-info').textContent=`Showing ${number(from)}–${number(to)} of ${number(groups[tracking.group].count)}`;
}
async function loadTracking(){
  if(tracking.busy){tracking.refreshPending=true;return;}tracking.busy=true;syncControls();error();el('updated').textContent='Refreshing…';el('gap-caption').textContent='Checking loaded transactions…';
  try{const data=await api('/api/counterparts?'+trackingParams(true));tracking.summary=data.summary;tracking.page=data.page;tracking.failed=false;renderTracking();el('updated').textContent='Refreshed '+new Date(data.generated_at_utc).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
  catch(e){tracking.failed=true;tracking.page=null;tracking.summary=null;error(e.message);el('updated').textContent='Refresh failed';for(const key of Object.keys(groupInfo)){el('count-'+key).textContent='—';const countries=el('countries-'+key);if(countries)countries.textContent='Results unavailable';}el('gap-caption').textContent='Use Refresh results to retry.';trackingEmpty('The tracking results could not be loaded. Please retry.');el('gap-page-info').textContent='Results unavailable';}
  finally{tracking.busy=false;syncControls();if(tracking.refreshPending){tracking.refreshPending=false;loadActive();}}
}
// Keep the shared workspace separate from its reconciliation modules.
const viewInfo={
  home:{title:'Home',eyebrow:'SPIRO OPERATIONS / WORKSPACE',description:'Your shared workspace for dashboards and operational reviews.'},
  overview:{title:'Wallet & swap reconciliation',eyebrow:'SWAP / WALLET & SWAP',description:'Track wallet deductions and investigate transactions that need attention.'},
  counterparts:{title:'Missing counterparts',eyebrow:'SWAP / MISSING COUNTERPARTS',description:'Investigate wallet deductions and swaps without a verified counterpart.'},
  due:{title:'Swap to Due',eyebrow:'SWAP / SWAP TO DUE',description:'Track due-created swaps and verify their repayment evidence.'},
  offer:{title:'Swap to Offer',eyebrow:'SWAP / SWAP TO OFFER',description:'Verify offer coverage using consumption and allocation evidence.'}
};
function selectView(view){
  if(!viewInfo[view]||state.busy||tracking.busy||due.busy||offers.busy)return;
  closeDetail();currentView=view;error();
  el('swap-navigation').classList.toggle('has-active',view!=='home');
  if(view!=='home')el('swap-navigation').open=true;
  for(const [name,id] of [['home','home-content'],['overview','overview-content'],['counterparts','gap-content'],['due','due-content'],['offer','offer-content']])el(id).hidden=name!==view;
  for(const id of ['filters','source-note','results-toolbar'])el(id).hidden=view==='home';
  document.querySelector('.status-filter').hidden=view!=='overview';
  for(const name of Object.keys(viewInfo)){
    const button=el('view-'+name);const selected=name===view;
    button.setAttribute('aria-pressed',String(selected));button.classList.toggle('active',selected);
    if(selected)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');
  }
  const info=viewInfo[view];el('page-title').textContent=info.title;el('page-eyebrow').textContent=info.eyebrow;el('page-description').textContent=info.description;
  document.title='Spiro | '+info.title;el('module-context').textContent=info.eyebrow.replace('SWAP / ','');
  el('status').value='';delete state.filters.status;resetPages();window.scrollTo(0,0);loadActive();
}
for(const name of Object.keys(viewInfo))el('view-'+name).addEventListener('click',()=>selectView(name));
for(const button of document.querySelectorAll('[data-open-view]'))button.addEventListener('click',()=>selectView(button.dataset.openView));
el('refresh-results').addEventListener('click',()=>{resetPages();loadActive();loadSources();});
el('overview-open-swaps').addEventListener('click',()=>{tracking.group='open_swaps';selectView('counterparts');});el('overview-paid-dues').addEventListener('click',()=>{due.group='resolved';el('due-group').value='resolved';selectView('due');});
el('overview-offers').addEventListener('click',()=>{offers.group='resolved';selectView('offer');});
function selectGroup(group){if(state.busy||tracking.busy)return;tracking.group=group;tracking.cursors=[null];tracking.index=0;loadTracking();}
for(const group of Object.keys(groupInfo))el('group-'+group).addEventListener('click',()=>selectGroup(group));el('gap-group').addEventListener('change',()=>selectGroup(el('gap-group').value));
el('gap-next').addEventListener('click',()=>{if(tracking.busy||!tracking.page?.has_more)return;tracking.cursors[tracking.index+1]=tracking.page.next_cursor;tracking.index++;loadTracking();});el('gap-previous').addEventListener('click',()=>{if(tracking.busy||!tracking.index)return;tracking.index--;loadTracking();});
function openTrackingDetail(r){
  state.returnFocus=document.activeElement;state.selected=r;el('drawer').hidden=false;el('drawer-overlay').hidden=false;el('close-drawer').focus();const body=el('drawer-content');body.replaceChildren(node('h2','',r.customer_name||r.record_type+' details'),node('span','badge',gapReasons[r.missing_counterpart_reason]||r.missing_counterpart_reason));const wallet=r.record_type==='Wallet deduction';let grid=node('dl','detail-grid');field(grid,'Country',r.country);field(grid,'Customer reference',r.customer_reference||r.mapped_customer_references);field(grid,'Customer ID',r.customer_id);field(grid,'Wallet',wallet?r.wallet_code||r.wallet_id:r.mapped_wallet_record_ids);body.append(node('h3','','Customer & wallet'),grid);
  grid=node('dl','detail-grid');field(grid,'Reference',r.wallet_reference||r.swap_reference);field(grid,'Transaction ID',r.transaction_id?.trim()||'Missing — cannot match by reference');field(grid,'Record ID',r.record_id);field(grid,'Amount',money(wallet?r.wallet_amount:r.swap_amount)+' '+(r.currency||'Unknown currency'));field(grid,'Created on',sourceTime(r.created_on));field(grid,'Status',r.wallet_status||r.swap_status);if(wallet){field(grid,'Transaction type',r.transaction_type);field(grid,'Settled against',r.settled_against);}else{field(grid,'Payment method',r.payment_method);field(grid,'Successful wallet payment',r.wallet_payment_expected?'Yes':'No');field(grid,'Station',r.station_label||r.station_code);field(grid,'Vehicle',r.vehicle_registration);field(grid,'Swap date',sourceTime(r.swap_date));field(grid,'Currency candidates',r.currency_candidates);}body.append(node('h3','',r.record_type),grid);
  grid=node('dl','detail-grid');field(grid,'Source file',r.source_file);field(grid,'Source row',r.source_row_number);field(grid,'Date context',r.date_context?.replaceAll('_',' '));field(grid,'First loaded counterpart',sourceTime(r.observed_first_swap||r.observed_first_wallet_deduction));field(grid,'Last loaded counterpart',sourceTime(r.observed_last_swap||r.observed_last_wallet_deduction));body.append(node('h3','','Source coverage'),grid,node('p','detail-note','Results reflect loaded exports. Missing identifiers prevent matching; a non-wallet swap may legitimately have no wallet deduction. Source completeness and any refund decision still need investigation.'));
}
el('gap-export').addEventListener('click',async()=>{if(tracking.busy||tracking.failed)return;tracking.busy=true;syncControls();error();el('gap-export').textContent='Exporting…';try{const response=await fetch('/api/counterparts/export?'+trackingParams());if(!response.ok){const data=await response.json();throw new Error(data.error||'Export failed.');}const url=URL.createObjectURL(await response.blob());const link=node('a');link.href=url;link.download=tracking.group+'_tracking.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error(e.message);}finally{el('gap-export').textContent='↓ Export group';tracking.busy=false;syncControls();if(tracking.refreshPending){tracking.refreshPending=false;loadActive();}}});
function dueParams(includePage=false){const q=new URLSearchParams();for(const key of ['country','start','end'])if(state.filters[key])q.set(key,state.filters[key]);q.set('group',due.group);if(includePage){q.set('limit','50');if(due.cursors[due.index])q.set('cursor',due.cursors[due.index]);}return q;}
function dueEmpty(message){const tr=node('tr');const td=node('td','empty-state',message);td.colSpan=9;tr.append(td);el('due-rows').replaceChildren(tr);}
function renderDue(){
  const s=due.summary;if(s.resolved_count===undefined)throw new Error('Stop the current PyCharm run and run main.py again to activate Paid Due resolutions.');el('due-total').textContent=number(s.swap_count);el('due-matched').textContent=number(s.resolved_count);el('due-review').textContent=number(s.needs_review_count);el('due-pending').textContent=number(s.pending_count);el('due-case-count').textContent=number(s.by_group[due.group]);el('due-group').value=due.group;el('due-caption').textContent=dueGroupInfo[due.group];
  el('due-countries').replaceChildren();if(!s.groups.length)el('due-countries').append(node('div','country-placeholder','No due-created swaps match these filters.'));
  for(const g of s.groups){const card=node('article','country-card');const top=node('div','country-top');top.append(node('span','country-icon',g.country==='Kenya'?'KE':'RW'));const title=node('div');title.append(node('h3','',g.country),node('div','currency-label',g.currency?g.currency+' · current wallet snapshot':g.currency_source==='ambiguous_wallet_snapshot'?'Currency differs across wallets':'Currency unavailable'));top.append(title);const value=node('div','rate',money(g.swap_amount));value.append(node('span','','recorded swap amount'));top.append(value);const stats=node('div','country-stats');stats.append(node('span','',number(g.swap_count)+' swaps'),node('span','',number(g.resolved_count)+' cleared by Paid Dues'),node('span','',number(g.needs_review_count)+' review'));card.append(top,stats);card.append(node('p','upload-dates','Linked Dues: Paid '+number(g.paid_count)+' · Pending '+number(g.pending_count)+' · Closed '+number(g.closed_count)));const source=s.due_sources?.find(item=>item.country===g.country);if(source){card.append(node('p','upload-dates','Loaded Dues (all dates): '+number(source.record_count)),node('p','upload-dates','Source status: Paid '+number(source.paid_count)+' · Pending '+number(source.pending_count)+' · Closed '+number(source.closed_count)));if(source.missing_swap_lookup_count)card.append(node('p','upload-warning',number(source.missing_swap_lookup_count)+' Due records have no swap lookup and cannot be matched automatically.'));if(source.export_limit_reached)card.append(node('p','upload-warning','A Due file reached the 200,000-row export limit. Verify coverage using the remaining date batches.'));}if(g.awaiting_due_export_count)card.append(node('p','upload-warning',number(g.awaiting_due_export_count)+' open swaps awaiting a '+g.country+' Due export.'));if(g.missing_amount_count)card.append(node('p','upload-warning',number(g.missing_amount_count)+' swaps have no amount and are excluded from this sum.'));el('due-countries').append(card);}
  el('due-coverage').textContent=s.awaiting_due_export_count?number(s.awaiting_due_export_count)+' swaps await a Due export for their country and remain open for review.':'Due matching reflects loaded exports. Source completeness still needs verification.';
  el('due-rows').replaceChildren();const records=due.page.records;if(!records.length)dueEmpty('No due-created swaps match the selected country and dates.');
  for(const r of records){const tr=node('tr');const customer=node('td');customer.append(node('div','customer-name',r.customer_name||'Customer unavailable'),node('div','cell-sub',r.customer_references?.join(', ')||r.customer_id||'No customer reference'));const country=node('td');country.append(node('span','country-chip',r.country));const ref=node('td');const reference=node('div','reference',r.swap_reference||r.record_id);reference.title=reference.textContent;ref.append(reference,node('div','cell-sub',r.swap_status||'Swap status unavailable'));const amount=node('td','amount-column');amount.append(node('span','amount',money(r.swap_amount)),node('span','amount-currency',r.currency||'?'));const dueRef=node('td','reference',r.due_reference|| (r.due_count>1?r.due_count+' Due records':'—'));const result=node('td');result.append(node('span','badge'+(r.due_record_status==='matched'?' good':''),dueResultLabels[r.due_record_status]||r.due_record_status));result.append(node('div','reason-sub',resolutionLabels[r.resolution_status]||'Needs review'));const status=node('td');status.append(node('span','badge'+(r.due_status==='Paid'?' good':''),r.due_status||(r.due_count>1?'Ambiguous':'Not available')));const action=node('td');const open=node('button','open-button','View ↗');open.setAttribute('aria-label','View due-created swap '+(r.swap_reference||r.record_id));open.addEventListener('click',()=>openDueDetail(r));action.append(open);tr.append(customer,country,ref,amount,dueRef,result,status,node('td','',sourceTime(r.created_on)),action);el('due-rows').append(tr);}
  const from=records.length?due.index*50+1:0;const to=records.length?due.index*50+records.length:0;el('due-page-info').textContent=`Showing ${number(from)}–${number(to)} of ${number(s.by_group[due.group])}`;
}
async function loadDue(){
  if(due.busy){due.refreshPending=true;return;}due.busy=true;syncControls();error();el('updated').textContent='Refreshing…';
  try{const data=await api('/api/due-swaps?'+dueParams(true));due.summary=data.summary;due.page=data.page;due.failed=false;renderDue();el('updated').textContent='Refreshed '+new Date(data.generated_at_utc).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}
  catch(e){due.failed=true;due.page=null;due.summary=null;error(e.message);el('updated').textContent='Refresh failed';for(const id of ['due-total','due-matched','due-review','due-pending','due-case-count'])el(id).textContent='—';el('due-countries').replaceChildren(node('div','country-placeholder','Results unavailable. Use Refresh results to retry.'));el('due-coverage').textContent='Results unavailable';dueEmpty('Due-created swaps could not be loaded. Please retry.');el('due-page-info').textContent='Results unavailable';}
  finally{due.busy=false;syncControls();if(due.refreshPending){due.refreshPending=false;loadActive();}}
}
