  let grid=node('dl','detail-grid');for(const [label,value] of [['Country',r.country],['Customer references',r.customer_references],['Customer ID',r.customer_id]])field(grid,label,value);body.append(node('h3','','Customer'),grid);
  grid=node('dl','detail-grid');for(const [label,value] of [['Swap reference',r.swap_reference],['Record ID',r.record_id],['Transaction ID',r.transaction_id||'Not supplied'],['Payment method',r.payment_method],['Swap status',r.swap_status],['Swap amount',money(r.swap_amount)+' '+(r.currency||'Unknown currency')],['Currency source',r.currency_source.replaceAll('_',' ')],['Created on',sourceTime(r.created_on)],['Swap date',r.swap_date],['Station',r.station],['Vehicle',r.vehicle_registration]])field(grid,label,value);body.append(node('h3','','Swap'),grid);
  grid=node('dl','detail-grid');field(grid,'Linked Due records',r.due_count);field(grid,'Match result',dueResultLabels[r.due_record_status]||r.due_record_status);field(grid,'Due status',r.due_status||r.repayment_status);field(grid,'Review resolution',resolutionLabels[r.resolution_status]||'Needs review');field(grid,'Attached wallet debits',r.wallet_debit_count);field(grid,'Swap source file',r.source_file);field(grid,'Source row',r.source_row_number);body.append(node('h3','','Due reconciliation'),grid);
  for(const d of r.dues){grid=node('dl','detail-grid');for(const [label,value] of [['Due reference',d.reference],['Due Record ID',d.record_id],['Customer ID',d.customer_id],['Due amount',money(d.amount)+' '+(d.currency||'Unknown currency')],['Original Due amount',money(d.original_amount)],['Due type',d.type],['Status (Zoho)',d.status],['Payment mode',d.payment_mode],['Settlement Transaction ID',d.transaction_id],['Due creation date',d.creation_date],['Settlement date',d.settlement_date],['Source modified',sourceTime(d.source_modified_at)],['Due source file',d.source_file]])field(grid,label,value);body.append(node('h3','','Due '+(d.reference||d.record_id)),grid);}
  body.append(node('p','detail-note','Links use the Due’s exact swap lookup and country. Paid, Pending and Closed reflect the source export; Closed does not establish repayment. Due Amount can remain populated on Paid records and is not a verified outstanding balance.'));
