function offerParams(paging=false){const q=new URLSearchParams();for(const key of ['country','start','end'])if(state.filters[key])q.set(key,state.filters[key]);q.set('group',offers.group);if(paging){q.set('limit','50');if(offers.cursors[offers.index])q.set('cursor',offers.cursors[offers.index]);}return q;}
function offerEmpty(message){const tr=node('tr');const td=node('td','empty-state',message);td.colSpan=8;tr.append(td);el('offer-rows').replaceChildren(tr);}
function renderOffers(){const s=offers.summary;for(const [id,key] of [['total','swap_count'],['resolved','resolved_count'],['review','needs_review_count'],['wallet','wallet_attached_count']])el('offer-'+id).textContent=number(s[key]);el('offer-case-count').textContent=number(s.by_group[offers.group]);el('offer-group').value=offers.group;
  el('offer-countries').replaceChildren();for(const c of s.by_country){const card=node('article','country-card');card.append(node('h3','',c.country));const stats=node('div','country-stats');for(const [label,key] of [['Offer swaps','swap_count'],['Cleared','resolved_count'],['Review','needs_review_count']]){const text=node('span','',label+' ');text.append(node('b','',number(c[key])));stats.append(text);}card.append(stats,node('p','upload-dates',number(c.wallet_attached_count)+' already have wallet deductions'));el('offer-countries').append(card);}if(!s.by_country.length)el('offer-countries').append(node('div','country-placeholder','No offer swaps match these filters.'));
  el('offer-sources').textContent=s.sources.map(r=>r.country+' '+r.module+': '+number(r.rows)+(r.missing_lookup_rows?' · '+number(r.missing_lookup_rows)+' missing lookups':'')).join(' | ')||'No offer exports loaded. Add allocation and consumption CSVs above.';el('offer-reasons').textContent=Object.entries(s.review_reasons).map(([reason,count])=>(offerLabels[reason]||reason)+': '+number(count)).join(' · ')||'No offer swaps need review in this selection.';
  el('offer-rows').replaceChildren();for(const r of offers.page.records){const tr=node('tr');const customer=node('td');customer.append(node('div','customer-name',r.customer_name||'Customer unavailable'),node('div','cell-sub',r.business_id||r.customer_id||'No customer reference'));const ref=node('td');ref.append(node('div','reference',r.swap_reference||r.record_id),node('div','cell-sub',r.swap_status));const result=node('td');result.append(node('span','badge'+(r.resolution_status==='resolved_offer'?' good':''),offerResolution[r.resolution_status]),node('div','reason-sub',offerLabels[r.offer_result]||r.offer_result));const action=node('td');const button=node('button','open-button','View ↗');button.setAttribute('aria-label','View offer swap '+(r.swap_reference||r.record_id));button.addEventListener('click',()=>openOfferDetail(r));action.append(button);tr.append(customer,node('td','',r.country),ref,node('td','reference',r.allocation_reference||'—'),node('td','',money(r.consumed_soc)+' / '+money(r.net_soc)),result,node('td','',sourceTime(r.created_on)),action);el('offer-rows').append(tr);}if(!offers.page.records.length)offerEmpty('No offer swaps in this result group.');const count=offers.page.records.length;el('offer-page-info').textContent=`Showing ${count?offers.index*50+1:0}–${count?offers.index*50+count:0} of ${number(s.by_group[offers.group])}`;el('offer-caption').textContent=offers.group==='resolved'?'Verified full SOC coverage; these swaps leave the open swap review.':'Inspect the linked consumption and allocation for each swap.';
}
async function loadOffers(){if(offers.busy){offers.refreshPending=true;return;}offers.busy=true;syncControls();error();el('updated').textContent='Refreshing…';try{const data=await api('/api/offer-swaps?'+offerParams(true));offers.summary=data.summary;offers.page=data.page;offers.failed=false;renderOffers();el('updated').textContent='Refreshed '+new Date(data.generated_at_utc).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}catch(e){offers.failed=true;offers.page=null;offers.summary=null;error(e.message);for(const id of ['total','resolved','review','wallet','case-count'])el('offer-'+id).textContent='—';el('offer-countries').replaceChildren();el('offer-sources').textContent='Results unavailable';el('offer-reasons').textContent='';offerEmpty('Offer results could not be loaded. Restart main.py if this view was just added.');el('offer-page-info').textContent='Results unavailable';el('updated').textContent='Refresh failed';}finally{offers.busy=false;syncControls();if(offers.refreshPending){offers.refreshPending=false;loadActive();}}}
function openOfferDetail(r){state.returnFocus=document.activeElement;state.selected=r;el('drawer').hidden=false;el('drawer-overlay').hidden=false;el('close-drawer').focus();const body=el('drawer-content');body.replaceChildren(node('h2','',r.customer_name||'Offer swap'),node('span','badge'+(r.resolution_status==='resolved_offer'?' good':''),offerResolution[r.resolution_status]),node('p','',offerLabels[r.offer_result]||r.offer_result));let grid=node('dl','detail-grid');for(const [label,value] of [['Country',r.country],['Customer ID',r.customer_id],['Customer reference',r.business_id],['Swap reference',r.swap_reference],['Swap Record ID',r.record_id],['Swap created',sourceTime(r.created_on)],['Swap amount',money(r.swap_amount)+' '+(r.currency||'?')],['Net SOC',money(r.net_soc)],['Billable SOC',money(r.billable_soc)],['Non-billable SOC',money(r.non_billable_soc)],['Attached wallet debits',r.wallet_debit_count],['Source file',r.source_file],['Source row',r.source_row_number]])field(grid,label,value);body.append(node('h3','','Swap'),grid);
  for(const c of r.consumptions){grid=node('dl','detail-grid');for(const [label,value] of [['Record ID',c.zoho_record_id],['Reference',c.consumption_reference],['Swap lookup',c.swap_record_id],['Allocation reference',c.allocation_reference],['Customer reference',c.customer_business_id],['Currency',c.currency],['Consumption date',c.consumption_date],['Offer name',c.offer_name],['Allocated SOC',c.allocated_soc],['Consumed SOC',c.consumed_soc],['Remaining SOC',c.remaining_soc],['Consumed discount',c.consumed_discount],['Source file',c.source_file],['Source row',c.source_row_number]])field(grid,label,value);body.append(node('h3','','Consumption'),grid);}
  for(const a of r.allocations){grid=node('dl','detail-grid');for(const [label,value] of [['Record ID',a.zoho_record_id],['Allocation reference',a.allocation_reference],['Customer ID',a.customer_id],['Offer reference',a.offer_reference],['Offer lookup',a.offer_id],['Type',a.offer_type],['Frequency',a.frequency],['Current status',a.status],['Allocation date',a.allocation_date],['Valid from',a.valid_from],['Valid till',a.valid_till],['Expiry date',a.expiry_date],['Total SOC',a.total_soc],['Consumed SOC',a.consumed_soc],['Loaded consumption SOC',r.loaded_consumed_soc],['Source file',a.source_file],['Source row',a.source_row_number]])field(grid,label,value);body.append(node('h3','','Allocation'),grid);}body.append(node('p','detail-note','Resolution checks use exact source links and full SOC voucher coverage. Allocation status is a current snapshot; historical use still needs valid dates. Conflicts remain open for investigation.'));}
el('offer-group').addEventListener('change',()=>{offers.group=el('offer-group').value;offers.cursors=[null];offers.index=0;loadOffers();});el('offer-next').addEventListener('click',()=>{if(offers.busy||!offers.page?.has_more)return;offers.cursors[offers.index+1]=offers.page.next_cursor;offers.index++;loadOffers();});el('offer-previous').addEventListener('click',()=>{if(offers.busy||!offers.index)return;offers.index--;loadOffers();});
el('offer-export').addEventListener('click',async()=>{if(offers.busy||offers.failed||!offers.page)return;offers.busy=true;syncControls();error();try{const response=await fetch('/api/offer-swaps/export?'+offerParams());if(!response.ok){const data=await response.json();throw new Error(data.error||'Export failed.');}const url=URL.createObjectURL(await response.blob());const link=node('a');link.href=url;link.download='spiro_offer_'+offers.group+'.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){error(e.message);}finally{offers.busy=false;syncControls();if(offers.refreshPending){offers.refreshPending=false;loadActive();}}});

